CREATE TEMPORARY VIEW tmp_order_detail_${grass_region_without_quote} AS
select  shop_id
        ,item_id
        ,model_id
        ,model_status
        ,full_start_timestamp
        ,sum(imp_cnt) as imp_cnt
        ,sum(sold_cnt) as order_cnt
        ,sum(gmv) as gmv
from    srdi_mart.dwm_sr_data_warehouse_tc_pb_reward_model_mini
where   grass_region = ${grass_region}
  and   local_date = ${local_date}
  and   local_hour = ${local_hour}
  and   model_status in (1, 2)
group by 1, 2, 3, 4, 5;

--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_tc_pb_reward_banner_model_1d
PARTITION(grass_region=${grass_region}, local_date=${local_date}, local_hour=${local_hour})
SELECT
    t.shop_id,
    t.model_id,
    ROW_NUMBER() OVER (PARTITION BY t.shop_id ORDER BY  t.order_cnt DESC, t.imp_cnt DESC, t.gmv DESC,t.model_id desc ) as rank_num,
    CEIL(ROW_NUMBER() OVER (PARTITION BY t.shop_id ORDER BY  t.order_cnt DESC, t.imp_cnt DESC, t.gmv DESC ,t.model_id desc)/10) as page_num,
    t.imp_cnt,
    t.order_cnt,
    t.gmv
FROM (
    SELECT
        shop_id,
        model_id,
        SUM(imp_cnt) as imp_cnt,
        SUM(order_cnt) as order_cnt,
        SUM(gmv) as gmv
    FROM tmp_order_detail_${grass_region_without_quote}
    GROUP BY shop_id, model_id
) t;
